/**
 * What the operator sees when asked to approve a secret's use.
 *
 * The lesson from agent-hijacking research (an injected agent buried its commands behind a harmless-looking approval
 * text) is that the confirmation must be generated by trusted code from the *actual* arguments, never from a summary the
 * model wrote, and must not hide anything: no truncation, no whitespace folding, no invisible characters. If the real
 * action cannot be shown in full, the answer is "no", not a shortened version of it.
 */

/** Room for the whole action inside Telegram's dialog (which cuts at 1500 characters including the header). */
export const MAX_ACTION_CHARS = 950;

// Bidi overrides/isolates, zero-width and invisible formatting characters, other C0/C1 controls (newline and tab stay).
const HIDDEN = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f\u00ad\u061c\u180e\u200b-\u200f\u2028\u2029\u202a-\u202e\u2060-\u206f\ufeff\ufff9-\ufffb]/gu;

/** Make every invisible or direction-changing character visible as `<U+XXXX>`; returns the text and whether anything was found. */
export function revealHidden(text: string): { text: string; found: boolean } {
	let found = false;
	const out = text.replace(HIDDEN, (c) => { found = true; return `<U+${c.codePointAt(0)!.toString(16).toUpperCase().padStart(4, "0")}>`; });
	return { text: out, found };
}

/** Hosts, IPs and e-mail style targets that appear in the action, extracted by us rather than reported by the model. */
export function addressesIn(text: string): string[] {
	const found = new Set<string>();
	for (const m of text.matchAll(/\b[a-z][a-z0-9+.-]*:\/\/(?:[^\s/@'"<>]+@)?(\[[0-9a-f:]+\]|[^\s/:?#'"<>]+)/gi)) found.add(m[1]!.toLowerCase());
	for (const m of text.matchAll(/[\w.+-]+@((?:[a-z0-9-]+\.)+[a-z]{2,}|\d{1,3}(?:\.\d{1,3}){3})\b/gi)) found.add(m[1]!.toLowerCase());
	for (const m of text.matchAll(/\b\d{1,3}(?:\.\d{1,3}){3}\b/g)) found.add(m[0]);
	for (const m of text.matchAll(/\b(?:[a-z0-9-]+\.)+(?:com|net|org|io|dev|app|cn|de|uk|us|jp|ru|xyz|top|cc|me|co|sh|ai|cloud|info|biz|tk|ml|ga|cf|gq)\b/gi)) found.add(m[0].toLowerCase());
	return [...found].slice(0, 10);
}

/**
 * Heuristic warnings about things the displayed text cannot show. These are advisory (a regex can never prove a command
 * is safe) and exist so a reviewer is told "what runs may be more than what you see".
 */
export function advisories(text: string): string[] {
	const out: string[] = [];
	if (/\|\s*(?:sudo\s+)?(?:ba|z|da|k)?sh\b|\|\s*(?:python3?|perl|ruby|node)\b|\beval\b|\$\(\s*(?:curl|wget)|`\s*(?:curl|wget)/.test(text)) out.push("会把内容交给解释器执行（管道到 shell、eval 或 $(curl …)），实际行为可能不止上面这些。");
	if (/(?:^|[\s;&|(])(?:ba|z|da|k)?sh\s+(?!-c\b)[^\s-][^\s]*|(?:^|[\s;&|(])(?:python3?|perl|ruby|node)\s+(?!-[ce]\b)[^\s-][^\s]*|(?:^|[\s;&|(])(?:source|\.)\s+\S+|(?:^|[\s;&|(])\.\/\S+/.test(text)) out.push("会运行一个本机脚本/程序文件，文件内容不在上面，无法在这里审阅。");
	if (/base64\s+(?:-d|--decode)|\bxxd\s+-r|\bopenssl\s+enc\b/.test(text)) out.push("包含解码步骤，真正执行的内容可能与显示的不同。");
	if (/\b(?:curl|wget|nc|ncat|socat|scp|rsync|ftp|sftp)\b|\/dev\/tcp\//.test(text)) out.push("包含网络传输命令，请核对下面的目标地址是不是你预期的。");
	return out;
}

export interface ApprovalInput {
	/** Header describing what is being unlocked, built from trusted data (entry title, vault name…). */
	subject: string;
	/** Why we are asking (flagged entry, over budget…). */
	reason: string;
	/** The exact command or tool arguments, as the harness received them. */
	action: string;
	/** Tool name, for context. */
	tool: string;
}

export type ApprovalText = { ok: true; message: string } | { ok: false; reason: string };

const clip = (t: string, n: number): string => (t.length > n ? `${t.slice(0, n - 1)}…` : t);

export function approvalMessage(i: ApprovalInput): ApprovalText {
	const shown = revealHidden(i.action);
	// Compare the *original* length too: expanding or stripping must never be what brings it under the limit.
	if (i.action.length > MAX_ACTION_CHARS || shown.text.length > MAX_ACTION_CHARS) {
		return { ok: false, reason: `The command/arguments are ${i.action.length} characters, too long to show the operator in full, so it was refused automatically. Use a shorter command, or ask the operator to run it themselves.` };
	}
	const addrs = addressesIn(shown.text);
	const warn = [...advisories(shown.text), ...(shown.found ? ["内容里有不可见或改变显示方向的字符，已用 <U+XXXX> 标出。"] : [])];
	// Everything the program worked out comes first and the model-supplied text comes last, so that if a dialog is ever cut
	// short it is the unverified part that is lost, never the warnings.
	return {
		ok: true,
		message: [
			clip(i.subject, 400),
			`原因：${clip(i.reason, 200)}`,
			...(warn.length ? ["", ...warn.map((w) => `⚠️ ${w}`)] : []),
			"",
			`出现的地址（由程序提取）：${addrs.length ? addrs.join("  ") : "无"}`,
			"",
			`—— ${i.tool} 将执行的完整内容（原样，由 AI 提出）——`,
			shown.text,
		].join("\n"),
	};
}
